options(stringsAsFactors = FALSE)
stopifnot(getRversion() == "4.6.1")
root <- normalizePath(getwd(), mustWork = TRUE)
out <- file.path(root, "audit/manuscript_nature_health/revision_2026_09_11/consolidated_display_repair_order72k")
record <- file.path(out, "environment_capture_recovery_001")
sha <- function(p) { con <- file(p, "rb"); on.exit(close(con)); unname(unclass(as.character(openssl::sha256(con)))) }
resolve <- function(p) if (startsWith(p, "/")) p else file.path(root, p)
stopifnot(!file.exists(file.path(record, "after_854_rows.csv")))
pins <- read.csv(file.path(record, "preflight_854_rows.csv"), check.names = FALSE)
pins$after_sha256 <- vapply(pins$path, function(p) sha(resolve(p)), character(1))
pins$after_exact <- pins$after_sha256 == pins$expected_sha256
write.csv(pins, file.path(record, "after_854_rows.csv"), row.names = FALSE)
stopifnot(nrow(pins) == 854L, all(pins$after_exact))
served <- read.csv(file.path(record, "served_preflight.csv"))
served$after_exact <- vapply(served$source, sha, character(1)) == served$sha256 & vapply(served$served, sha, character(1)) == served$sha256
write.csv(served, file.path(record, "served_after.csv"), row.names = FALSE)
stopifnot(all(served$after_exact))
prior <- read.csv(file.path(record, "completed_captures_before.csv"))
prior$after_exact <- vapply(prior$path, sha, character(1)) == prior$sha256
write.csv(prior, file.path(record, "completed_captures_after.csv"), row.names = FALSE)
stopifnot(nrow(prior) == 19L, all(prior$after_exact))
capture <- file.path(out, "capture_s2_attempt3")
manifest <- jsonlite::fromJSON(file.path(capture, "word_table_png_manifest.json"), simplifyVector = FALSE)[[1L]]
stopifnot(manifest$key == "supp_table_s2", length(manifest$files) == 3L)
source <- xml2::read_html(file.path(root, "audit/manuscript_nature_health/figure_table_selection_assets/tbl-near-eye-metrics.html"))
parts <- lapply(manifest$files, function(x) xml2::read_html(sub("\\.png$", ".html", x$path)))
rows <- function(doc) xml2::xml_find_all(doc, ".//tbody/tr")
row_text <- function(doc) vapply(rows(doc), function(row) paste(xml2::xml_text(xml2::xml_children(row)), collapse = "\u001f"), character(1))
payloads <- function(doc) unname(xml2::xml_attr(xml2::xml_find_all(doc, ".//tbody//img"), "src"))
source_widths <- lengths(lapply(rows(source), xml2::xml_children))
checks <- data.frame(check = c("all_23_rows_once_in_order", "17_metric_rows_14_columns", "six_group_rows", "all_17_image_payloads_exact", "all_three_complete_headers", "notes_only_last_part_and_exact", "three_full_horizontal_column_sets", "helper_numeric_rectangle_checks_empty", "visual_no_clipping"), pass = c(identical(unname(row_text(source)), unlist(lapply(parts, row_text), use.names = FALSE)), sum(source_widths == 14L) == 17L, sum(source_widths == 1L) == 6L, length(payloads(source)) == 17L && identical(payloads(source), unlist(lapply(parts, payloads), use.names = FALSE)), all(vapply(parts, function(x) identical(xml2::xml_text(xml2::xml_find_first(x, ".//thead")), xml2::xml_text(xml2::xml_find_first(source, ".//thead"))), logical(1))), all(vapply(parts[1:2], function(x) length(xml2::xml_find_all(x, ".//tfoot")) == 0L, logical(1))) && identical(xml2::xml_text(xml2::xml_find_first(parts[[3]], ".//tfoot")), xml2::xml_text(xml2::xml_find_first(source, ".//tfoot"))), all(vapply(manifest$files, function(x) identical(as.integer(unlist(x$columns)), 0:13), logical(1))), all(vapply(manifest$files, function(x) length(x$verification$numericalTextOverflow) == 0L, logical(1))), FALSE), qualification = c(rep("Protected structure or text comparison, no scientific recalculation", 8), "Visual FAIL: Unit HH:MM and Scaling threshold are clipped in narrow fixed columns; numerical3-12 checks do not cover these columns"))
write.csv(checks, file.path(record, "capture_structure_and_visual_checks.csv"), row.names = FALSE)
stopifnot(all(checks$pass[1:8]))
files <- list.files(capture, full.names = TRUE)
write.csv(data.frame(path = files, sha256 = vapply(files, sha, character(1)), bytes = file.info(files)$size), file.path(record, "attempt3_output_pins.csv"), row.names = FALSE)
writeLines(c("Identity and protected cell/image checks only. Successful capture execution is not visual acceptance.", capture.output(sessionInfo())), file.path(record, "after_session.txt"))
cat("Preservation PASS854 rows,19 old captures,12 served pairs; S2 structure8/8 PASS; visual FAIL for Unit/Scaling clipping.\n")
